inline auto bits_exp2_tuned(T x) -> T
{
    const auto t = std::trunc((x + T(-0.04367744890360167)) * T(0x1p23));
    return std::bit_cast<float>(static_cast<std::uint32_t>(static_cast<std::int32_t>(t) + (127 << 23)));
}

